   100	    /// <summary>La combinaison exacte qui compte le moins de billets, ou <c>null</c>.</summary>
   101	    private static NoteCounts? FindCombination(int amount, NoteCounts available)
   102	    {
   103	        NoteCounts? best = null;
   104	        for (var fifties = 0; fifties <= available.Fifties && fifties * 50 <= amount; fifties++)
   105	        {
   106	            for (var twenties = 0; twenties <= available.Twenties && fifties * 50 + twenties * 20 <= amount; twenties++)
   107	            {
   108	                var rest = amount - fifties * 50 - twenties * 20;
   109	                if (rest % 10 != 0 || rest / 10 > available.Tens)
   110	                {
   111	                    continue;
   112	                }
   113	
   114	                var candidate = new NoteCounts(fifties, twenties, rest / 10);
   115	                if (best is not { } current || candidate.Total < current.Total)
   116	                {
   117	                    best = candidate;
   118	                }
   119	            }
   120	        }
   121	
   122	        return best;
   123	    }
   124	
   125	    /// <summary>Découpe la combinaison en passages de 4 billets au plus.</summary>
   126	    private static IEnumerable<NoteCounts> SplitIntoPasses(NoteCounts notes)
   127	    {
   128	        var remaining = notes;
   129	        while (remaining.Total > 0)
   130	        {
   131	            var room = MaxNotesPerPass;
   132	            var fifties = Math.Min(remaining.Fifties, room);
   133	            room -= fifties;
   134	            var twenties = Math.Min(remaining.Twenties, room);
   135	            room -= twenties;
   136	            var tens = Math.Min(remaining.Tens, room);
   137	
   138	            var pass = new NoteCounts(fifties, twenties, tens);
   139	            remaining -= pass;
   140	
   141	            yield return pass;
   142	        }
   143	    }
