    [Property(Replay = Graine, MaxTest = Cas, Arbitrary = new[] { typeof(Domaine) })]
    public void Retrait_Servable_SortEnPassagesDeUnAQuatreBillets_QuiFontLaCombinaison(RetraitServable cas)
